using System;using System.Collections;using System.Reflection;using System.Linq;using System.IO;using System.Collections.Generic;using BepInEx;using UnityEngine;using Jotunn.Managers;using RunicLilyPads;
[BepInPlugin("chazman.IvySmoke","Ivy validation","1.2.0")][BepInDependency("chazman.RunicLilyPads")]
public partial class IvySmoke:BaseUnityPlugin{
 bool ready;int errors;string root;const BindingFlags Hidden=BindingFlags.Instance|BindingFlags.NonPublic;
 void Awake(){root=Path.GetFullPath(Path.Combine(Paths.BepInExRootPath,".."));Utils.SetSaveDataPath(root+"/saves");PrefabManager.OnVanillaPrefabsAvailable+=()=>ready=true;StartCoroutine(Environment.GetEnvironmentVariable("IVY_NETWORK")=="server"?Server():Run());}
 bool Joined(IvyLights i)=>(bool)typeof(IvyLights).GetField("Joined",Hidden).GetValue(i);
 void Check(bool ok,string name){if(!ok)errors++;Logger.LogInfo((ok?"IVY PASS ":"IVY FAIL ")+name);}
 IEnumerator Run(){float until=Time.realtimeSinceStartup+90;while(!ready&&Time.realtimeSinceStartup<until)yield return null;
  if(Environment.GetEnvironmentVariable("IVY_NETWORK")=="client"){yield return Client();yield break;}
  var w=World.GetCreateWorld("IvyValidation",FileHelpers.FileSource.Local);Game.SetProfile("ivy_validation",FileHelpers.FileSource.Local);ZNet.SetServer(true,false,false,"IvyValidation","",w);ZNet.ResetServerHost();typeof(FejdStartup).GetMethod("LoadMainScene",Hidden).Invoke(UnityEngine.Object.FindObjectOfType<FejdStartup>(),null);
  until=Time.realtimeSinceStartup+160;while(!Player.m_localPlayer&&Time.realtimeSinceStartup<until)yield return null;if(!Player.m_localPlayer){Check(false,"world load");Finish();yield break;}
  SetupPlayer();yield return new WaitForSecondsRealtime(3);
  if(File.Exists(root+"/chain-saved.txt")){var pieces=UnityEngine.Object.FindObjectsOfType<IvyLights>().Where(i=>i.GetComponent<ZNetView>().GetZDO()?.GetBool("wg_ivy_join",false)==true).ToArray();Check(pieces.Length>0,"joined extensions survive process restart");foreach(var i in pieces)Check(Joined(i),"joined appearance loaded from saved state");Finish();yield break;}
  yield return Checks();Game.instance.SavePlayerProfile(true);typeof(ZNet).GetMethod("SaveWorld",Hidden).Invoke(ZNet.instance,new object[]{false});File.WriteAllText(root+"/chain-saved.txt","saved");yield return new WaitForSecondsRealtime(2);Finish();
 }
 Vector3 origin;
 void SetupPlayer(){var p=Player.m_localPlayer;p.SetGodMode(true);foreach(var b in UnityEngine.Object.FindObjectsOfType<Valkyrie>())b.DropPlayer(true);p.SetIntro(false);var v=File.ReadAllText(root+"/persisted-position.txt").Split(',');origin=new Vector3(float.Parse(v[0]),float.Parse(v[1])+8,float.Parse(v[2]));for(int i=0;i<40&&Location.IsInsideNoBuildLocation(origin);i++)origin+=Vector3.right*15;p.transform.position=origin;p.GetComponent<Rigidbody>().position=origin;p.GetComponent<Rigidbody>().isKinematic=true;}
 IEnumerator Checks(){
  var p=Player.m_localPlayer;var prefab=PrefabManager.Instance.GetPrefab("piece_arcanedecor_ivy_gold_hanging");var piece=prefab.GetComponent<Piece>();
  p.AddKnownItem(PrefabManager.Instance.GetPrefab("Stone").GetComponent<ItemDrop>().m_itemData);p.SetNoPlacementCost(true);var table=PrefabManager.Instance.GetPrefab("Hammer").GetComponent<ItemDrop>().m_itemData.m_shared.m_buildPieces;typeof(Player).GetMethod("SetPlaceMode",Hidden).Invoke(p,new object[]{table});Check(p.SetSelectedPiece(piece),"select hanging ivy through Hammer");
  foreach(float scale in new[]{.25f,1f,2f}){
   var parent=Instantiate(prefab,origin,Quaternion.Euler(0,scale==2?60:0,0));parent.GetComponent<ZNetView>().GetZDO().Set("wg_tree_scale",scale);yield return null;yield return null;var visual=parent.transform.Find("garden_visual");var expected=visual.TransformPoint(new Vector3(0,-1.35f,0));
   foreach(float y in new[]{-1.04f,-1.5f,-1.95f}){
    var aim=visual.TransformPoint(new Vector3(y==-1.5f?.34f:0,y,0));var cam=GameCamera.instance.transform;cam.position=aim+Vector3.back*2;cam.LookAt(aim);p.transform.position=aim+new Vector3(0,-1,-2);p.GetComponent<Rigidbody>().position=p.transform.position;Physics.SyncTransforms();
    var start=Time.realtimeSinceStartup;typeof(Player).GetMethod("UpdatePlacementGhost",Hidden).Invoke(p,new object[]{false});var ghost=(GameObject)typeof(Player).GetField("m_placementGhost",Hidden).GetValue(p);var status=(Player.PlacementStatus)typeof(Player).GetField("m_placementStatus",Hidden).GetValue(p);
    Check(status==Player.PlacementStatus.Valid&&Vector3.Distance(ghost.transform.position,expected)<.03f,"lower-half snap scale="+scale+" y="+y+" status="+status+" distance="+Vector3.Distance(ghost.transform.position,expected));Check(Joined(ghost.GetComponent<IvyLights>()),"preview hides top");Check(Quaternion.Angle(ghost.transform.rotation,parent.transform.rotation)<.1f,"extension follows parent orientation");Check(Time.realtimeSinceStartup-start<.1f,"snap feedback under 100ms");
   }
   var ghost2=(GameObject)typeof(Player).GetField("m_placementGhost",Hidden).GetValue(p);var before=UnityEngine.Object.FindObjectsOfType<IvyLights>();p.PlacePiece(piece,ghost2.transform.position,ghost2.transform.rotation,false);yield return null;yield return null;var added=UnityEngine.Object.FindObjectsOfType<IvyLights>().FirstOrDefault(i=>i.gameObject!=ghost2&&!before.Contains(i));Check(added&&Joined(added)&&added.GetComponent<ZNetView>().GetZDO().GetBool("wg_ivy_join",false),"placed extension saves hidden top");
   if(added){Check(Math.Abs(added.transform.Find("garden_visual").localScale.x-scale)<.01f,"extension starts at parent size");var full=parent.GetComponentInChildren<MeshFilter>().sharedMesh.GetTriangles(0).Length;Check(added.GetComponentInChildren<MeshFilter>().sharedMesh.GetTriangles(0).Length<full,"attachment loop geometry removed");if(scale==1){Capture(parent,added.gameObject);var pos=added.transform.position;Check(added.Interact(p,false,false),"joined ivy opens its menu on first interaction");typeof(IvyLights).GetMethod("SetSize",Hidden).Invoke(added,new object[]{1.5f});typeof(IvyLights).GetMethod("SetBulbs",Hidden).Invoke(added,new object[]{2f});Check(Joined(added)&&added.transform.position==pos&&Math.Abs(added.transform.Find("garden_visual").localScale.x-1.5f)<.01f,"joined ivy resize and bulb edit preserve hidden top and anchor");typeof(IvyLights).GetMethod("Cancel",Hidden).Invoke(added,null);Check(Joined(added)&&Math.Abs(added.transform.Find("garden_visual").localScale.x-1)<.01f,"cancel restores joined ivy size");}}
   if(added&&scale==1){var av=added.transform.Find("garden_visual");var aim=av.TransformPoint(new Vector3(0,-1.7f,0));GameCamera.instance.transform.position=aim+Vector3.back*2;GameCamera.instance.transform.LookAt(aim);p.transform.position=aim+new Vector3(0,-1,-2);p.GetComponent<Rigidbody>().position=p.transform.position;Physics.SyncTransforms();typeof(Player).GetMethod("UpdatePlacementGhost",Hidden).Invoke(p,new object[]{false});Check(Joined(ghost2.GetComponent<IvyLights>())&&Vector3.Distance(ghost2.transform.position,av.TransformPoint(new Vector3(0,-1.35f,0)))<.03f,"extension accepts another extension");}
   var upper=visual.TransformPoint(new Vector3(0,-.4f,0));GameCamera.instance.transform.position=upper+Vector3.back*2;GameCamera.instance.transform.LookAt(upper);p.transform.position=upper+new Vector3(0,-1,-2);p.GetComponent<Rigidbody>().position=p.transform.position;Physics.SyncTransforms();typeof(Player).GetMethod("UpdatePlacementGhost",Hidden).Invoke(p,new object[]{false});Check(!Joined(ghost2.GetComponent<IvyLights>()),"upper half does not join");
   origin+=Vector3.right*4;
  }
  TestHammer("piece_arcanedecor_ivy_gold_hanging",origin);TestHammer("piece_arcanedecor_ivy_gold_clinging",origin+Vector3.right*4);
  typeof(Player).GetMethod("SetPlaceMode",Hidden).Invoke(p,new object[]{null});
 }
 void Capture(GameObject a,GameObject b){var all=a.GetComponentsInChildren<Transform>().Concat(b.GetComponentsInChildren<Transform>()).ToArray();var layers=all.Select(t=>t.gameObject.layer).ToArray();foreach(var t in all)t.gameObject.layer=30;var bounds=a.GetComponentInChildren<MeshRenderer>().bounds;bounds.Encapsulate(b.GetComponentInChildren<MeshRenderer>().bounds);var host=new GameObject("chain capture");var cam=host.AddComponent<Camera>();cam.enabled=false;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=Color.clear;cam.cullingMask=1<<30;cam.orthographic=true;cam.orthographicSize=bounds.extents.y*1.12f;cam.transform.position=bounds.center+Vector3.back*6;cam.transform.LookAt(bounds.center);var rt=new RenderTexture(512,900,24);cam.targetTexture=rt;cam.Render();var old=RenderTexture.active;RenderTexture.active=rt;var tex=new Texture2D(512,900,TextureFormat.RGBA32,false);tex.ReadPixels(new Rect(0,0,512,900),0,0);tex.Apply();File.WriteAllBytes(root+"/chain.png",ImageConversion.EncodeToPNG(tex));RenderTexture.active=old;cam.targetTexture=null;rt.Release();Destroy(rt);Destroy(tex);Destroy(host);for(int i=0;i<all.Length;i++)all[i].gameObject.layer=layers[i];}
 void Finish(){Logger.LogInfo(errors==0?"IVY COMPLETE PASS":"IVY COMPLETE FAIL "+errors);Application.Quit(errors==0?0:1);}
 IEnumerator Server(){float until=Time.realtimeSinceStartup+260;while(Time.realtimeSinceStartup<until){if(ZNet.instance&&ZDOMan.instance!=null&&ZNet.instance.GetPeers().Any(p=>p.IsReady())){var list=new List<ZDO>();int index=0;while(!ZDOMan.instance.GetAllZDOsWithPrefabIterative("piece_arcanedecor_ivy_gold_hanging",list,ref index)){}if(list.Any(z=>z.GetBool("wg_ivy_join",false))){Check(true,"separate server observed joined extension state");yield break;}}yield return new WaitForSecondsRealtime(1);}Check(false,"server observation timeout");}
 IEnumerator Client(){var profile=new PlayerProfile("ivy_network",FileHelpers.FileSource.Local);profile.SetName("IvyTest");profile.m_firstSpawn=false;profile.Save();Game.SetProfile("ivy_network",FileHelpers.FileSource.Local);var f=UnityEngine.Object.FindObjectOfType<FejdStartup>();HarmonyLib.AccessTools.Property(typeof(FejdStartup),"ServerPassword").SetValue(null,"ivytest123");HarmonyLib.AccessTools.Field(typeof(FejdStartup),"m_joinServer").SetValue(f,new ServerJoinData(new ServerJoinDataDedicated("127.0.0.1:2476")));HarmonyLib.AccessTools.Field(typeof(FejdStartup),"m_instantStart").SetValue(f,true);f.JoinServer();float until=Time.realtimeSinceStartup+150;while(!Player.m_localPlayer&&Time.realtimeSinceStartup<until)yield return null;Check(Player.m_localPlayer&&!ZNet.instance.IsServer(),"genuinely joined separate server");if(!Player.m_localPlayer){Finish();yield break;}SetupPlayer();yield return new WaitForSecondsRealtime(2);yield return Checks();yield return new WaitForSecondsRealtime(8);Finish();}
}



